#include <iiGUI/DesktopCommon.h>
#include <iiGUI/AndroidJni.h>
namespace ii::gui {
core::Result<ClipboardContent> read_clipboard(){try{
    detail::AndroidJni j;auto* e=j.env;auto manager=j.clipboard();auto type=j.type("android/content/ClipboardManager");auto clip=e->CallObjectMethod(manager,j.method(type,"getPrimaryClip","()Landroid/content/ClipData;"));j.check();if(!clip)return ClipboardContent{};
    auto clip_type=j.type("android/content/ClipData");const auto count=e->CallIntMethod(clip,j.method(clip_type,"getItemCount","()I"));j.check();if(count<=0)return ClipboardContent{};
    auto item=e->CallObjectMethod(clip,j.method(clip_type,"getItemAt","(I)Landroid/content/ClipData$Item;"),0);j.check();auto chars=e->CallObjectMethod(item,j.method(j.type("android/content/ClipData$Item"),"getText","()Ljava/lang/CharSequence;"));j.check();
    if(!chars){auto uri=e->CallObjectMethod(item,j.method(j.type("android/content/ClipData$Item"),"getUri","()Landroid/net/Uri;"));j.check();ClipboardContent result;if(uri){auto string=static_cast<jstring>(e->CallObjectMethod(uri,j.method(j.type("android/net/Uri"),"toString","()Ljava/lang/String;")));j.check();result.url=j.string(string);}if(!detail::valid_clipboard(result))return core::fail(core::ErrorCode::out_of_range,"Clipboard URI exceeds budget");return result;}
    auto string=static_cast<jstring>(e->CallObjectMethod(chars,j.method(j.type("java/lang/CharSequence"),"toString","()Ljava/lang/String;")));j.check();ClipboardContent result;result.text=j.string(string);if(!detail::valid_clipboard(result))return core::fail(core::ErrorCode::out_of_range,"Clipboard text exceeds UTF-8 budget");return result;
}catch(...){return core::fail(core::ErrorCode::failed,"Cannot read Android clipboard",std::current_exception());}}
core::Result<void> write_clipboard(const ClipboardContent& value){if(!detail::valid_clipboard(value))return core::fail(core::ErrorCode::invalid_argument,"Invalid clipboard payload");if(!value.files.empty()||!value.image.empty())return core::fail(core::ErrorCode::unsupported,"Android clipboard currently accepts text and URLs");try{
    detail::AndroidJni j;auto type=j.type("android/content/ClipData");auto clip=j.env->CallStaticObjectMethod(type,j.static_method(type,"newPlainText","(Ljava/lang/CharSequence;Ljava/lang/CharSequence;)Landroid/content/ClipData;"),j.string("iiGUI"),j.string(value.text.empty()?value.url:value.text));j.check();j.env->CallVoidMethod(j.clipboard(),j.method(j.type("android/content/ClipboardManager"),"setPrimaryClip","(Landroid/content/ClipData;)V"),clip);j.check();return {};
}catch(...){return core::fail(core::ErrorCode::failed,"Cannot write Android clipboard",std::current_exception());}}
core::Result<void> open_external_url(std::string_view value){if(!detail::valid_external_url(value))return core::fail(core::ErrorCode::invalid_argument,"Invalid external URL");try{
    detail::AndroidJni j;auto uri=j.type("android/net/Uri");auto parsed=j.env->CallStaticObjectMethod(uri,j.static_method(uri,"parse","(Ljava/lang/String;)Landroid/net/Uri;"),j.string(value));j.check();auto intent=j.type("android/content/Intent");auto object=j.env->NewObject(intent,j.method(intent,"<init>","(Ljava/lang/String;Landroid/net/Uri;)V"),j.string("android.intent.action.VIEW"),parsed);j.check();j.env->CallVoidMethod(j.activity,j.method(j.type("android/app/Activity"),"startActivity","(Landroid/content/Intent;)V"),object);j.check();return {};
}catch(...){return core::fail(core::ErrorCode::failed,"Android could not open the external URL",std::current_exception());}}
}
